PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS departments(id INTEGER PRIMARY KEY AUTOINCREMENT,code TEXT UNIQUE NOT NULL,name TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS semesters(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,academic_year TEXT NOT NULL,start_date TEXT NOT NULL,end_date TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('Planned','Active','Closed')));
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT,username TEXT UNIQUE NOT NULL,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN('admin','teacher','student')),display_name TEXT NOT NULL,is_active INTEGER NOT NULL DEFAULT 1,must_change_password INTEGER NOT NULL DEFAULT 1,failed_attempts INTEGER NOT NULL DEFAULT 0,locked_until TEXT,last_login TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS teachers(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER UNIQUE NOT NULL,employee_no TEXT UNIQUE NOT NULL,department_id INTEGER NOT NULL,designation TEXT,qualification TEXT,phone TEXT,joining_date TEXT,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(department_id) REFERENCES departments(id));
CREATE TABLE IF NOT EXISTS sections(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,department_id INTEGER NOT NULL,semester_id INTEGER NOT NULL,capacity INTEGER NOT NULL DEFAULT 40,UNIQUE(name,semester_id),FOREIGN KEY(department_id) REFERENCES departments(id),FOREIGN KEY(semester_id) REFERENCES semesters(id));
CREATE TABLE IF NOT EXISTS students(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER UNIQUE NOT NULL,registration_no TEXT UNIQUE NOT NULL,department_id INTEGER NOT NULL,section_id INTEGER,status TEXT NOT NULL DEFAULT 'Active',phone TEXT,admission_date TEXT,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(department_id) REFERENCES departments(id),FOREIGN KEY(section_id) REFERENCES sections(id));
CREATE TABLE IF NOT EXISTS courses(id INTEGER PRIMARY KEY AUTOINCREMENT,code TEXT UNIQUE NOT NULL,name TEXT NOT NULL,credit_hours INTEGER NOT NULL CHECK(credit_hours BETWEEN 1 AND 6),department_id INTEGER NOT NULL,recommended_semester INTEGER,FOREIGN KEY(department_id) REFERENCES departments(id));
CREATE TABLE IF NOT EXISTS rooms(id INTEGER PRIMARY KEY AUTOINCREMENT,room_no TEXT UNIQUE NOT NULL,building TEXT NOT NULL,capacity INTEGER NOT NULL,room_type TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS offerings(id INTEGER PRIMARY KEY AUTOINCREMENT,course_id INTEGER NOT NULL,teacher_id INTEGER NOT NULL,section_id INTEGER NOT NULL,semester_id INTEGER NOT NULL,max_students INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'Active',UNIQUE(course_id,section_id,semester_id),FOREIGN KEY(course_id) REFERENCES courses(id),FOREIGN KEY(teacher_id) REFERENCES teachers(id),FOREIGN KEY(section_id) REFERENCES sections(id),FOREIGN KEY(semester_id) REFERENCES semesters(id));
CREATE TABLE IF NOT EXISTS schedules(id INTEGER PRIMARY KEY AUTOINCREMENT,offering_id INTEGER NOT NULL,room_id INTEGER NOT NULL,day_of_week TEXT NOT NULL,start_time TEXT NOT NULL,end_time TEXT NOT NULL,FOREIGN KEY(offering_id) REFERENCES offerings(id) ON DELETE CASCADE,FOREIGN KEY(room_id) REFERENCES rooms(id));
CREATE TABLE IF NOT EXISTS enrollments(id INTEGER PRIMARY KEY AUTOINCREMENT,student_id INTEGER NOT NULL,offering_id INTEGER NOT NULL,enrollment_date TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'Active',UNIQUE(student_id,offering_id),FOREIGN KEY(student_id) REFERENCES students(id),FOREIGN KEY(offering_id) REFERENCES offerings(id));
CREATE TABLE IF NOT EXISTS attendance_sessions(id INTEGER PRIMARY KEY AUTOINCREMENT,offering_id INTEGER NOT NULL,class_date TEXT NOT NULL,topic TEXT,created_by INTEGER NOT NULL,UNIQUE(offering_id,class_date),FOREIGN KEY(offering_id) REFERENCES offerings(id),FOREIGN KEY(created_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS attendance_records(id INTEGER PRIMARY KEY AUTOINCREMENT,session_id INTEGER NOT NULL,student_id INTEGER NOT NULL,status TEXT NOT NULL CHECK(status IN('Present','Absent','Late','Excused')),remarks TEXT,UNIQUE(session_id,student_id),FOREIGN KEY(session_id) REFERENCES attendance_sessions(id) ON DELETE CASCADE,FOREIGN KEY(student_id) REFERENCES students(id));
CREATE TABLE IF NOT EXISTS assessments(id INTEGER PRIMARY KEY AUTOINCREMENT,offering_id INTEGER NOT NULL,name TEXT NOT NULL,type TEXT NOT NULL,max_marks REAL NOT NULL,weight REAL NOT NULL,assessment_date TEXT NOT NULL,FOREIGN KEY(offering_id) REFERENCES offerings(id));
CREATE TABLE IF NOT EXISTS assessment_results(id INTEGER PRIMARY KEY AUTOINCREMENT,assessment_id INTEGER NOT NULL,student_id INTEGER NOT NULL,marks REAL NOT NULL,feedback TEXT,UNIQUE(assessment_id,student_id),FOREIGN KEY(assessment_id) REFERENCES assessments(id) ON DELETE CASCADE,FOREIGN KEY(student_id) REFERENCES students(id));
CREATE TABLE IF NOT EXISTS audit_logs(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER,action TEXT NOT NULL,entity TEXT NOT NULL,entity_id INTEGER,details TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id));
